fn no_repeat(cells: List[Str]) -> Bool {
  let filled = cells.filter(fn(c) => c != ".")
  return filled.unique().len() == filled.len()
}

pub fn sudoku(rows: List[Str]) -> Bool {
  if rows.len() != 9 {
    return false
  }
  var grid: List[List[Str]] = []
  for r in rows {
    if r.len() != 9 {
      return false
    }
    for ch in r.chars() {
      if ch != "." and "123456789".contains(ch) == false {
        return false
      }
    }
    grid = grid.push(r.chars())
  }
  let g = grid
  for k in range(0, 9) {
    if no_repeat(g.get_or(k, [])) == false {
      return false
    }
    let column = g.map(fn(row) => row.get_or(k, "."))
    if no_repeat(column) == false {
      return false
    }
  }
  for b in range(0, 9) {
    let r0 = (b / 3) * 3
    let c0 = (b % 3) * 3
    let box = range(0, 9).map(fn(q) => g.get_or(r0 + q / 3, []).get_or(c0 + q % 3, "."))
    if no_repeat(box) == false {
      return false
    }
  }
  return true
}
